import { useNavigate } from "react-router-dom";

const AuthCheck = (navigate) => {
    const token = localStorage.getItem("token");

    if (!token) {
        navigate("/login/");
        return false;
    }

    return true;
};

export const useAuthNavigate = () => {
    return useNavigate();
};

export default AuthCheck;
